// Jonker-Volgenant dense LAP, double costs.
// Adapted from the well-known public implementation structure (lapjv).
// Returns column index for each row.
#include <cmath>
#include <cstdlib>
#include <cstdint>
#include <vector>
#include <algorithm>
#include <limits>
#include <iostream>
#include <chrono>
#include <random>

using namespace std;

static const double BIG = 1e18;

// Solve min-cost assignment. cost is row-major n*n.
// col_for_row[i] = assigned column.
void lapjv(const double* cost, int n, int* col_for_row) {
    vector<double> u(n, 0.0), v(n, 0.0), d(n);
    vector<int> rowsol(n, -1), colsol(n, -1), pred(n);
    vector<int> free_rows(n);
    vector<int> todo(n);
    vector<char> label(n);

    // Column reduction
    for (int j = n - 1; j >= 0; --j) {
        double minv = cost[j];
        int imin = 0;
        for (int i = 1; i < n; ++i) {
            double cij = cost[i * n + j];
            if (cij < minv) { minv = cij; imin = i; }
        }
        v[j] = minv;
        if (rowsol[imin] == -1) {
            rowsol[imin] = j;
            colsol[j] = imin;
        }
    }

    int nfree = 0;
    for (int i = 0; i < n; ++i) {
        if (rowsol[i] == -1) free_rows[nfree++] = i;
    }

    // Reduction transfer
    for (int i = 0; i < n; ++i) {
        int j1 = rowsol[i];
        if (j1 >= 0) {
            double minv = BIG;
            const double* row = cost + i * n;
            for (int j = 0; j < n; ++j) {
                if (j == j1) continue;
                double red = row[j] - v[j];
                if (red < minv) minv = red;
            }
            v[j1] -= minv;
        }
    }

    // Augmenting row reduction
    for (int stage = 0; stage < 2; ++stage) {
        int k = 0;
        int prev = nfree;
        nfree = 0;
        while (k < prev) {
            int i = free_rows[k++];
            const double* row = cost + i * n;
            double umin = row[0] - v[0];
            int j1 = 0;
            double usub = BIG;
            int j2 = -1;
            for (int j = 1; j < n; ++j) {
                double h = row[j] - v[j];
                if (h < usub) {
                    if (h >= umin) {
                        usub = h; j2 = j;
                    } else {
                        usub = umin; umin = h; j2 = j1; j1 = j;
                    }
                }
            }
            int i0 = colsol[j1];
            if (umin < usub) {
                v[j1] -= (usub - umin);
            } else if (i0 >= 0 && j2 >= 0) {
                j1 = j2;
                i0 = colsol[j1];
            }
            rowsol[i] = j1;
            colsol[j1] = i;
            if (i0 >= 0) {
                if (umin < usub) {
                    free_rows[--k] = i0;
                } else {
                    free_rows[nfree++] = i0;
                }
            }
        }
    }

    // Augmentation
    for (int f = 0; f < nfree; ++f) {
        int freerow = free_rows[f];
        const double* frow = cost + freerow * n;
        for (int j = 0; j < n; ++j) {
            d[j] = frow[j] - v[j];
            pred[j] = freerow;
            label[j] = 1;
            todo[j] = j;
        }
        int ntodo = n;
        int min_idx = 0;
        double minv = d[0];
        for (int t = 1; t < ntodo; ++t) {
            if (d[todo[t]] < minv) { minv = d[todo[t]]; min_idx = t; }
        }
        int endofpath = -1;
        while (true) {
            int jmin = todo[min_idx];
            todo[min_idx] = todo[--ntodo];
            label[jmin] = 2;
            int i_ass = colsol[jmin];
            if (i_ass < 0) { endofpath = jmin; break; }
            double h = cost[i_ass * n + jmin] - v[jmin] - minv;
            const double* arow = cost + i_ass * n;
            for (int t = 0; t < ntodo; ++t) {
                int j = todo[t];
                double cred = arow[j] - v[j] - h;
                if (cred < d[j]) {
                    d[j] = cred;
                    pred[j] = i_ass;
                }
            }
            if (ntodo == 0) break;
            minv = d[todo[0]];
            min_idx = 0;
            for (int t = 1; t < ntodo; ++t) {
                if (d[todo[t]] < minv) { minv = d[todo[t]]; min_idx = t; }
            }
        }
        double thresh = d[endofpath];
        for (int j = 0; j < n; ++j) {
            if (label[j] == 2) v[j] += d[j] - thresh;
        }
        int j = endofpath;
        while (true) {
            int i = pred[j];
            colsol[j] = i;
            int jnext = rowsol[i];
            rowsol[i] = j;
            if (i == freerow) break;
            j = jnext;
        }
    }

    for (int i = 0; i < n; ++i) col_for_row[i] = rowsol[i];
}

int main() {
    int n = 600;
    vector<double> cost(n * n);
    mt19937 rng(1);
    uniform_real_distribution<double> dist(0.0, 1.0);
    // euclidean-like
    vector<double> ax(n), ay(n), bx(n), by(n);
    for (int i = 0; i < n; ++i) { ax[i]=dist(rng); ay[i]=dist(rng); bx[i]=dist(rng); by[i]=dist(rng); }
    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j) {
            double dx = ax[i]-bx[j], dy = ay[i]-by[j];
            cost[i*n+j] = sqrt(dx*dx+dy*dy);
        }
    vector<int> sol(n);
    auto t0 = chrono::high_resolution_clock::now();
    lapjv(cost.data(), n, sol.data());
    auto t1 = chrono::high_resolution_clock::now();
    double ms = chrono::duration<double, milli>(t1-t0).count();
    // check permutation
    vector<int> seen(n, 0);
    int bad = 0;
    for (int i = 0; i < n; ++i) {
        if (sol[i] < 0 || sol[i] >= n || seen[sol[i]]) bad++;
        else seen[sol[i]] = 1;
    }
    cout << "ms=" << ms << " bad=" << bad << " nfree-check done\n";
    return 0;
}
