// Faster JV: maintain running minimum during scan (no second pass),
// and use column reduction + augmenting row reduction so few augmentations remain.
// Also try WITHOUT the slow reduction if nfree is large... we'll print nfree.
#include <cmath>
#include <vector>
#include <iostream>
#include <chrono>
#include <random>
#include <cstdint>
using namespace std;

static const double BIG = 1e18;

struct Result { double ms; int nfree_after; int aug_scans; };

Result lapjv(const double* cost, int n, int* col_for_row) {
    vector<double> v(n, 0.0), d(n);
    vector<int> rowsol(n, -1), colsol(n, -1), pred(n);
    vector<int> free_rows(n), todo(n);
    vector<char> scanned(n);

    auto t0 = chrono::high_resolution_clock::now();

    // Column reduction (reverse so ties prefer later columns — matches many impls)
    for (int j = n - 1; j >= 0; --j) {
        double minv = cost[j];
        int imin = 0;
        for (int i = 1; i < n; ++i) {
            double cij = cost[(size_t)i * n + j];
            if (cij < minv) { minv = cij; imin = i; }
        }
        v[j] = minv;
        if (rowsol[imin] == -1) {
            rowsol[imin] = j;
            colsol[j] = imin;
        }
    }
    int nfree = 0;
    for (int i = 0; i < n; ++i) if (rowsol[i] == -1) free_rows[nfree++] = i;

    // Reduction transfer
    for (int i = 0; i < n; ++i) {
        int j1 = rowsol[i];
        if (j1 < 0) continue;
        const double* row = cost + (size_t)i * n;
        double minv = BIG;
        for (int j = 0; j < n; ++j) {
            if (j == j1) continue;
            double red = row[j] - v[j];
            if (red < minv) minv = red;
        }
        v[j1] -= minv;
    }

    // Augmenting row reduction, 2 stages
    for (int stage = 0; stage < 2; ++stage) {
        int k = 0, prev = nfree;
        nfree = 0;
        while (k < prev) {
            int i = free_rows[k++];
            const double* row = cost + (size_t)i * n;
            double umin = row[0] - v[0];
            int j1 = 0;
            double usub = BIG;
            int j2 = -1;
            for (int j = 1; j < n; ++j) {
                double h = row[j] - v[j];
                if (h < usub) {
                    if (h >= umin) { usub = h; j2 = j; }
                    else { usub = umin; umin = h; j2 = j1; j1 = j; }
                }
            }
            int i0 = colsol[j1];
            if (umin < usub) v[j1] -= (usub - umin);
            else if (i0 >= 0 && j2 >= 0) { j1 = j2; i0 = colsol[j1]; }
            rowsol[i] = j1;
            colsol[j1] = i;
            if (i0 >= 0) {
                if (umin < usub) free_rows[--k] = i0;
                else free_rows[nfree++] = i0;
            }
        }
    }
    int nfree_after = nfree;

    long long scans = 0;
    // Augmentation with running-min maintained by a simple linear scan,
    // but we ONLY scan the todo list once per extraction and track min on the fly
    // by keeping a "current threshold" and a ready list of columns at the minimum.
    // This is the REAL JV trick: columns are split into SCAN (to explore) and
    // a ready set of those achieving the current lowest reduced distance.
    vector<int> scan(n), ready(n);
    for (int f = 0; f < nfree; ++f) {
        int freerow = free_rows[f];
        const double* frow = cost + (size_t)freerow * n;
        int nscan = 0;
        double minv = BIG;
        int nready = 0;
        for (int j = 0; j < n; ++j) {
            double dj = frow[j] - v[j];
            d[j] = dj;
            pred[j] = freerow;
            if (dj < minv) {
                minv = dj;
                nready = 0;
                ready[nready++] = j;
            } else if (dj == minv) {
                ready[nready++] = j;
            } else {
                scan[nscan++] = j;
            }
        }
        int endofpath = -1;
        while (true) {
            if (nready == 0) {
                // find new min among scan
                if (nscan == 0) break;
                minv = d[scan[0]];
                int new_nscan = 0;
                nready = 0;
                for (int t = 0; t < nscan; ++t) {
                    int j = scan[t];
                    double dj = d[j];
                    if (dj < minv) {
                        // previous ready go back to scan
                        for (int r = 0; r < nready; ++r) scan[new_nscan++] = ready[r];
                        minv = dj;
                        nready = 0;
                        ready[nready++] = j;
                    } else if (dj == minv) {
                        ready[nready++] = j;
                    } else {
                        scan[new_nscan++] = j;
                    }
                }
                nscan = new_nscan;
            }
            int jmin = ready[--nready];
            scans++;
            int i_ass = colsol[jmin];
            if (i_ass < 0) { endofpath = jmin; break; }
            double h = cost[(size_t)i_ass * n + jmin] - v[jmin] - minv;
            const double* arow = cost + (size_t)i_ass * n;
            // update scan list; columns that reach minv move to ready
            int new_nscan = 0;
            for (int t = 0; t < nscan; ++t) {
                int j = scan[t];
                double cred = arow[j] - v[j] - h;
                if (cred < d[j]) {
                    d[j] = cred;
                    pred[j] = i_ass;
                }
                if (d[j] == minv || d[j] < minv) {
                    // numerical: cred could be slightly below minv; treat as ready
                    if (d[j] < minv) {
                        // shouldn't often happen if duals are consistent; push anyway
                        minv = d[j];
                    }
                    ready[nready++] = j;
                } else {
                    scan[new_nscan++] = j;
                }
            }
            nscan = new_nscan;
        }
        double thresh = d[endofpath];
        // dual update: all columns not in scan and not in ready were removed as jmin
        // i.e. labeled. Easier to mark.
        // We didn't mark. Mark now: a column is labeled if it is neither in scan nor ready
        // AND we need ALL removed jmins including endofpath.
        // Let's just recompute with a label array — redo dual via labels we should have kept.
        // Fix: use a label. For now mark by reconstructing: set label during loop.
        // (We'll set labels properly in the cleaned version; here approximate by
        // scanning which columns have been removed. Use a side array.)
        // SKIP dual correctness test here — we'll fix.
        // Augment
        int j = endofpath;
        while (true) {
            int i = pred[j];
            colsol[j] = i;
            int jnext = rowsol[i];
            rowsol[i] = j;
            if (i == freerow) break;
            j = jnext;
        }
        // NOTE duals NOT updated — this will be incorrect after first aug.
        // This file is only to measure the inner-loop speed of one augmentation style.
        // We'll break after timing structure on a correct version below.
        break;
    }

    auto t1 = chrono::high_resolution_clock::now();
    for (int i = 0; i < n; ++i) col_for_row[i] = rowsol[i];
    Result r;
    r.ms = chrono::duration<double, milli>(t1 - t0).count();
    r.nfree_after = nfree_after;
    r.aug_scans = (int)scans;
    return r;
}

int main() {
    int n = 600;
    vector<double> ax(n), ay(n), bx(n), by(n), cost((size_t)n*n);
    mt19937 rng(1);
    uniform_real_distribution<double> dist(0.0, 1.0);
    for (int i = 0; i < n; ++i) { ax[i]=dist(rng); ay[i]=dist(rng); bx[i]=dist(rng); by[i]=dist(rng); }
    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j) {
            double dx=ax[i]-bx[j], dy=ay[i]-by[j];
            cost[(size_t)i*n+j] = sqrt(dx*dx+dy*dy);
        }
    vector<int> sol(n);
    // warmup
    auto r = lapjv(cost.data(), n, sol.data());
    cout << "nfree_after_reduction=" << r.nfree_after << " ms_partial=" << r.ms << "\n";
}
