#include <pybind11/pybind11.h>
#include <pybind11/numpy.h>
#include <vector>
#include <cmath>
#include <cstdint>
#include <limits>

namespace py = pybind11;

// Min-cost assignment via column reduction + shortest augmenting paths.
// cost: (n, n) float64 C-contiguous.
// returns int32 array col_for_row.
py::array_t<int32_t> solve_assignment(py::array_t<double, py::array::c_style | py::array::forcecast> cost) {
    auto buf = cost.request();
    if (buf.ndim != 2 || buf.shape[0] != buf.shape[1]) {
        throw std::runtime_error("cost must be square");
    }
    const int n = (int)buf.shape[0];
    const double* M = static_cast<const double*>(buf.ptr);

    std::vector<double> v(n);
    std::vector<int32_t> rowsol(n, -1), colsol(n, -1), pred(n);
    std::vector<char> scanned(n);
    std::vector<double> d(n);

    // column reduction, reverse order (tie-break: higher column index wins first claim)
    for (int j = n - 1; j >= 0; --j) {
        double minv = M[j];
        int imin = 0;
        for (int i = 1; i < n; ++i) {
            double cij = M[(size_t)i * n + j];
            if (cij < minv) { minv = cij; imin = i; }
        }
        v[j] = minv;
        if (rowsol[imin] == -1) {
            rowsol[imin] = j;
            colsol[j] = imin;
        }
    }

    // reduction transfer
    for (int i = 0; i < n; ++i) {
        int j1 = rowsol[i];
        if (j1 < 0) continue;
        const double* row = M + (size_t)i * n;
        double minv = std::numeric_limits<double>::infinity();
        for (int j = 0; j < n; ++j) {
            if (j == j1) continue;
            double red = row[j] - v[j];
            if (red < minv) minv = red;
        }
        v[j1] -= minv;
    }

    // augment free rows
    for (int freerow = 0; freerow < n; ++freerow) {
        if (rowsol[freerow] >= 0) continue;
        const double* frow = M + (size_t)freerow * n;
        for (int j = 0; j < n; ++j) {
            d[j] = frow[j] - v[j];
            pred[j] = freerow;
            scanned[j] = 0;
        }
        int endofpath = -1;
        // O(n) extractions, each O(n) scan — acceptable if well optimized
        for (int it = 0; it < n; ++it) {
            int jmin = -1;
            double mind = std::numeric_limits<double>::infinity();
            for (int j = 0; j < n; ++j) {
                if (!scanned[j] && d[j] < mind) { mind = d[j]; jmin = j; }
            }
            scanned[jmin] = 1;
            int i_ass = colsol[jmin];
            if (i_ass < 0) { endofpath = jmin; break; }
            double h = M[(size_t)i_ass * n + jmin] - v[jmin] - mind;
            const double* arow = M + (size_t)i_ass * n;
            for (int j = 0; j < n; ++j) {
                if (scanned[j]) continue;
                double cred = arow[j] - v[j] - h;
                if (cred < d[j]) {
                    d[j] = cred;
                    pred[j] = i_ass;
                }
            }
        }
        double thresh = d[endofpath];
        for (int j = 0; j < n; ++j) {
            if (scanned[j]) v[j] += d[j] - thresh;
        }
        int j = endofpath;
        while (true) {
            int i = pred[j];
            colsol[j] = i;
            int jnext = rowsol[i];
            rowsol[i] = j;
            if (i == freerow) break;
            j = jnext;
        }
    }

    py::array_t<int32_t> out(n);
    auto o = out.mutable_unchecked<1>();
    for (int i = 0; i < n; ++i) o(i) = rowsol[i];
    return out;
}

PYBIND11_MODULE(sap_ext, m) {
    m.def("solve_assignment", &solve_assignment, "Min-cost assignment");
}
