#include <Python.h>
#include <numpy/arrayobject.h>
#include <math.h>
#include <stdlib.h>
#include <stdint.h>

/*
 * Jonker-Volgenant dense LAP.
 * Column reduction + reduction transfer + 2x augmenting row reduction
 * + shortest augmenting path with a SCAN/READY split (columns at the
 * current minimum distance are "ready" and not re-scanned).
 */
static PyObject* solve_assignment(PyObject* self, PyObject* args) {
    PyObject* cost_obj;
    if (!PyArg_ParseTuple(args, "O", &cost_obj)) return NULL;
    PyArrayObject* cost = (PyArrayObject*)PyArray_FROM_OTF(cost_obj, NPY_FLOAT64, NPY_ARRAY_IN_ARRAY);
    if (!cost) return NULL;
    if (PyArray_NDIM(cost) != 2 || PyArray_DIM(cost, 0) != PyArray_DIM(cost, 1)) {
        Py_DECREF(cost);
        PyErr_SetString(PyExc_ValueError, "cost must be square");
        return NULL;
    }
    int n = (int)PyArray_DIM(cost, 0);
    double* M = (double*)PyArray_DATA(cost);
    const double BIG = 1e18;

    double* v = (double*)malloc(sizeof(double) * n);
    double* d = (double*)malloc(sizeof(double) * n);
    int* rowsol = (int*)malloc(sizeof(int) * n);
    int* colsol = (int*)malloc(sizeof(int) * n);
    int* pred = (int*)malloc(sizeof(int) * n);
    int* free_rows = (int*)malloc(sizeof(int) * n);
    int* scan = (int*)malloc(sizeof(int) * n);
    int* ready = (int*)malloc(sizeof(int) * n);
    char* labeled = (char*)malloc(n);
    if (!v||!d||!rowsol||!colsol||!pred||!free_rows||!scan||!ready||!labeled) {
        Py_DECREF(cost); PyErr_NoMemory(); return NULL;
    }
    for (int i = 0; i < n; ++i) { rowsol[i] = -1; colsol[i] = -1; }

    /* ---- column reduction (reverse: higher j claims a row first) ---- */
    for (int j = n - 1; j >= 0; --j) {
        double minv = M[j];
        int imin = 0;
        for (int i = 1; i < n; ++i) {
            double cij = M[(size_t)i * n + j];
            if (cij < minv) { minv = cij; imin = i; }
        }
        v[j] = minv;
        if (rowsol[imin] == -1) {
            rowsol[imin] = j;
            colsol[j] = imin;
        }
    }

    int nfree = 0;
    for (int i = 0; i < n; ++i) if (rowsol[i] < 0) free_rows[nfree++] = i;

    /* ---- reduction transfer ---- */
    for (int i = 0; i < n; ++i) {
        int j1 = rowsol[i];
        if (j1 < 0) continue;
        double* row = M + (size_t)i * n;
        double minv = BIG;
        for (int j = 0; j < n; ++j) {
            if (j == j1) continue;
            double red = row[j] - v[j];
            if (red < minv) minv = red;
        }
        v[j1] -= minv;
    }

    /* ---- augmenting row reduction (2 stages) ---- */
    for (int stage = 0; stage < 2; ++stage) {
        int k = 0, prev = nfree;
        nfree = 0;
        while (k < prev) {
            int i = free_rows[k++];
            double* row = M + (size_t)i * n;
            double umin = row[0] - v[0];
            int j1 = 0;
            double usub = BIG;
            int j2 = -1;
            for (int j = 1; j < n; ++j) {
                double h = row[j] - v[j];
                if (h < usub) {
                    if (h >= umin) { usub = h; j2 = j; }
                    else { usub = umin; umin = h; j2 = j1; j1 = j; }
                }
            }
            int i0 = colsol[j1];
            if (umin < usub) {
                v[j1] -= (usub - umin);
            } else if (i0 >= 0 && j2 >= 0) {
                j1 = j2;
                i0 = colsol[j1];
            }
            rowsol[i] = j1;
            colsol[j1] = i;
            if (i0 >= 0) {
                if (umin < usub) {
                    free_rows[--k] = i0; /* retry immediately */
                } else {
                    free_rows[nfree++] = i0;
                }
            }
        }
    }

    /* ---- augmentation with READY/SCAN split ---- */
    for (int f = 0; f < nfree; ++f) {
        int freerow = free_rows[f];
        double* frow = M + (size_t)freerow * n;
        int nscan = 0, nready = 0;
        double minv = BIG;
        for (int j = 0; j < n; ++j) {
            double dj = frow[j] - v[j];
            d[j] = dj;
            pred[j] = freerow;
            labeled[j] = 0;
            if (dj < minv) {
                /* previous ready become scan */
                for (int r = 0; r < nready; ++r) scan[nscan++] = ready[r];
                minv = dj;
                nready = 0;
                ready[nready++] = j;
            } else if (dj == minv) {
                ready[nready++] = j;
            } else {
                scan[nscan++] = j;
            }
        }
        int endofpath = -1;
        while (1) {
            if (nready == 0) {
                if (nscan == 0) break;
                /* find new minimum among scan, partition */
                minv = BIG;
                int new_nscan = 0;
                nready = 0;
                for (int t = 0; t < nscan; ++t) {
                    int j = scan[t];
                    double dj = d[j];
                    if (dj < minv) {
                        for (int r = 0; r < nready; ++r) scan[new_nscan++] = ready[r];
                        minv = dj;
                        nready = 0;
                        ready[nready++] = j;
                    } else if (dj == minv) {
                        ready[nready++] = j;
                    } else {
                        scan[new_nscan++] = j;
                    }
                }
                nscan = new_nscan;
                if (nready == 0) break;
            }
            int jmin = ready[--nready];
            labeled[jmin] = 1;
            int i_ass = colsol[jmin];
            if (i_ass < 0) { endofpath = jmin; break; }
            double h = M[(size_t)i_ass * n + jmin] - v[jmin] - minv;
            double* arow = M + (size_t)i_ass * n;
            int new_nscan = 0;
            for (int t = 0; t < nscan; ++t) {
                int j = scan[t];
                double cred = arow[j] - v[j] - h;
                double dj = d[j];
                if (cred < dj) {
                    d[j] = cred;
                    pred[j] = i_ass;
                    dj = cred;
                }
                if (dj <= minv) {
                    ready[nready++] = j;
                } else {
                    scan[new_nscan++] = j;
                }
            }
            nscan = new_nscan;
        }
        double thresh = d[endofpath];
        for (int j = 0; j < n; ++j) {
            if (labeled[j]) v[j] += d[j] - thresh;
        }
        /* also columns still in ready were at minv == thresh, delta 0, skip */
        int j = endofpath;
        while (1) {
            int i = pred[j];
            colsol[j] = i;
            int jnext = rowsol[i];
            rowsol[i] = j;
            if (i == freerow) break;
            j = jnext;
        }
    }

    npy_intp dims[1] = {n};
    PyObject* out = PyArray_SimpleNew(1, dims, NPY_INT32);
    int32_t* odata = (int32_t*)PyArray_DATA((PyArrayObject*)out);
    for (int i = 0; i < n; ++i) odata[i] = rowsol[i];

    free(v); free(d); free(rowsol); free(colsol); free(pred);
    free(free_rows); free(scan); free(ready); free(labeled);
    Py_DECREF(cost);
    return out;
}

static PyMethodDef methods[] = {
    {"solve_assignment", solve_assignment, METH_VARARGS, "JV assignment"},
    {NULL, NULL, 0, NULL}
};
static struct PyModuleDef moduledef = {
    PyModuleDef_HEAD_INIT, "sap2", NULL, -1, methods
};
PyMODINIT_FUNC PyInit_sap2(void) {
    import_array();
    return PyModule_Create(&moduledef);
}
