#include <Python.h>
#include <numpy/arrayobject.h>
#include <math.h>
#include <stdlib.h>
#include <stdint.h>

/*
 * Bertsekas auction algorithm for the assignment problem.
 * epsilon-scaling. Returns an optimal assignment for the scaled problem;
 * with a final epsilon below the cost gap it is optimal for the original.
 *
 * For floating costs we run until epsilon is tiny and also verify nothing —
 * caller compares to reference.
 */
static PyObject* solve_assignment(PyObject* self, PyObject* args) {
    PyObject* cost_obj;
    double eps_factor = 0.2;
    if (!PyArg_ParseTuple(args, "O|d", &cost_obj, &eps_factor)) return NULL;
    PyArrayObject* cost = (PyArrayObject*)PyArray_FROM_OTF(
        cost_obj, NPY_FLOAT64, NPY_ARRAY_IN_ARRAY);
    if (!cost) return NULL;
    int n = (int)PyArray_DIM(cost, 0);
    double* M = (double*)PyArray_DATA(cost);

    double* price = (double*)calloc((size_t)n, sizeof(double));
    int* owner = (int*)malloc(sizeof(int) * (size_t)n);       /* row owning column, -1 free */
    int* rowsol = (int*)malloc(sizeof(int) * (size_t)n);
    int* unassigned = (int*)malloc(sizeof(int) * (size_t)n);
    if (!price || !owner || !rowsol || !unassigned) {
        Py_DECREF(cost); PyErr_NoMemory(); return NULL;
    }

    /* cost scale */
    double cmax = 0.0, cmin = 1e300;
    for (size_t i = 0; i < (size_t)n * (size_t)n; ++i) {
        double c = M[i];
        if (c > cmax) cmax = c;
        if (c < cmin) cmin = c;
    }
    double eps = (cmax - cmin) / 4.0;
    if (eps < 1e-6) eps = 1e-6;
    /* target: for unique optimum of geometric costs, a small eps suffices.
       We scale down to 1e-9 * range / n which is safe for exactness on float64 costs
       whose gaps are typically >> 1e-12. */
    double eps_target = (cmax - cmin) / ((double)n * 1e6);
    if (eps_target < 1e-12) eps_target = 1e-12;

    while (1) {
        for (int j = 0; j < n; ++j) owner[j] = -1;
        for (int i = 0; i < n; ++i) rowsol[i] = -1;
        int nfree = n;
        for (int i = 0; i < n; ++i) unassigned[i] = i;

        int guard = 0;
        int guard_max = n * n * 4;
        while (nfree > 0 && guard++ < guard_max) {
            int i = unassigned[--nfree];
            double* row = M + (size_t)i * (size_t)n;
            /* best and second best profit = -cost - price? 
               We minimize cost, so value of assigning j is -(Mij) - price[j],
               person bids to maximize value, i.e. minimize Mij + price[j]. */
            int j1 = 0;
            double best = row[0] + price[0];
            double second = 1e300;
            for (int j = 1; j < n; ++j) {
                double val = row[j] + price[j];
                if (val < second) {
                    if (val >= best) {
                        second = val;
                    } else {
                        second = best;
                        best = val;
                        j1 = j;
                    }
                }
            }
            /* bid: raise price so this object is eps worse than second best */
            double bid = price[j1] + (second - best) + eps;
            price[j1] = bid;
            int prev = owner[j1];
            owner[j1] = i;
            rowsol[i] = j1;
            if (prev >= 0) {
                unassigned[nfree++] = prev;
                rowsol[prev] = -1;
            }
        }
        if (eps <= eps_target) break;
        eps *= eps_factor;
        if (eps < eps_target) eps = eps_target;
    }

    npy_intp dims[1] = {n};
    PyObject* out = PyArray_SimpleNew(1, dims, NPY_INT32);
    int32_t* odata = (int32_t*)PyArray_DATA((PyArrayObject*)out);
    for (int i = 0; i < n; ++i) odata[i] = (int32_t)rowsol[i];
    free(price); free(owner); free(rowsol); free(unassigned);
    Py_DECREF(cost);
    return out;
}

static PyMethodDef methods[] = {
    {"solve_assignment", solve_assignment, METH_VARARGS, "auction"},
    {NULL, NULL, 0, NULL}
};
static struct PyModuleDef moduledef = {
    PyModuleDef_HEAD_INIT, "auction", NULL, -1, methods
};
PyMODINIT_FUNC PyInit_auction(void) {
    import_array();
    return PyModule_Create(&moduledef);
}
