#include <Python.h>
#include <numpy/arrayobject.h>
#include <math.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>

/*
 * Epsilon-scaling forward/reverse auction (Bertsekas) on a dense cost matrix.
 * Minimization form: person i bids on object j minimizing Mij + price[j].
 *
 * Forward: unassigned persons bid, raising prices.
 * Reverse: objects whose price can be lowered (profit margin) are offered
 * to a second-best person, which assigns people faster and cuts bidding wars.
 *
 * This is the "forward-reverse" auction used by the classic AUCTION code.
 * We implement a practical variant:
 *   - Gauss-Seidel forward auction (one person at a time) 
 *   - interleaved with a reverse phase that assigns free objects by
 *     decreasing their price to the point a free or better person wants them.
 */
static PyObject* solve_assignment(PyObject* self, PyObject* args) {
    PyObject* cost_obj;
    if (!PyArg_ParseTuple(args, "O", &cost_obj)) return NULL;
    PyArrayObject* cost = (PyArrayObject*)PyArray_FROM_OTF(
        cost_obj, NPY_FLOAT64, NPY_ARRAY_IN_ARRAY);
    if (!cost) return NULL;
    int n = (int)PyArray_DIM(cost, 0);
    double* M = (double*)PyArray_DATA(cost);

    double* price = (double*)calloc((size_t)n, sizeof(double)); /* object prices */
    double* profit = (double*)malloc(sizeof(double) * (size_t)n); /* person profits (best value, negated cost) */
    int* owner = (int*)malloc(sizeof(int) * (size_t)n);
    int* rowsol = (int*)malloc(sizeof(int) * (size_t)n);
    int* unassigned = (int*)malloc(sizeof(int) * (size_t)n);
    char* obj_free = (char*)malloc((size_t)n);

    double cmax = -1e300, cmin = 1e300;
    /* sample scale from a subset to save time? full scan is 600^2 ~ fine (3ms) */
    for (size_t t = 0, N = (size_t)n * (size_t)n; t < N; t += 17) {
        double c = M[t];
        if (c > cmax) cmax = c;
        if (c < cmin) cmin = c;
    }
    double range = cmax - cmin;
    if (range < 1e-9) range = 1e-9;
    double eps = range / 4.0;
    double eps_target = range / ((double)n * 1e6);
    if (eps_target < 1e-12) eps_target = 1e-12;

    while (1) {
        for (int j = 0; j < n; ++j) owner[j] = -1;
        for (int i = 0; i < n; ++i) { rowsol[i] = -1; profit[i] = 1e300; }
        int nfree = n;
        for (int i = 0; i < n; ++i) unassigned[i] = i;

        int iter = 0;
        int iter_max = n * 40;
        while (nfree > 0 && iter++ < iter_max) {
            /* ---- forward bids for a batch of unassigned persons ---- */
            int batch = nfree;
            /* process current unassigned; new displacements go to a side list */
            int* displaced = unassigned; /* reuse carefully: copy count */
            int nd = 0;
            int count = nfree;
            nfree = 0;
            for (int b = 0; b < count; ++b) {
                int i = displaced[b];
                double* row = M + (size_t)i * (size_t)n;
                int j1 = 0;
                double best = row[0] + price[0];
                double second = 1e300;
                for (int j = 1; j < n; ++j) {
                    double val = row[j] + price[j];
                    if (val < second) {
                        if (val >= best) second = val;
                        else { second = best; best = val; j1 = j; }
                    }
                }
                profit[i] = best;
                double newprice = price[j1] + (second - best) + eps;
                int prev = owner[j1];
                if (prev == i) {
                    /* already owner, just refresh price if beneficial */
                    if (newprice > price[j1]) price[j1] = newprice;
                    continue;
                }
                price[j1] = newprice;
                owner[j1] = i;
                rowsol[i] = j1;
                if (prev >= 0) {
                    rowsol[prev] = -1;
                    unassigned[nfree++] = prev;
                }
            }

            if (nfree == 0) break;

            /* ---- reverse phase: for each free object, find the person who
               wants it most and lower its price so that person bids.
               A free object j offers itself at a price that makes it the best
               choice for the person with the largest margin. ---- */
            for (int j = 0; j < n; ++j) obj_free[j] = (owner[j] < 0);
            /* Only do reverse if many are free — it costs O(n^2).
               Scan persons and for each, look at their best FREE object. */
            if (nfree > n / 8) {
                for (int t = 0; t < nfree; ++t) {
                    int i = unassigned[t];
                    if (rowsol[i] >= 0) continue;
                    double* row = M + (size_t)i * (size_t)n;
                    int jbest = -1;
                    double best = 1e300;
                    for (int j = 0; j < n; ++j) {
                        if (!obj_free[j]) continue;
                        double val = row[j] + price[j];
                        if (val < best) { best = val; jbest = j; }
                    }
                    if (jbest < 0) continue;
                    /* assign i to free object at current price (no raise beyond eps) */
                    price[jbest] = price[jbest]; /* unchanged; feasibility restored by eps later */
                    owner[jbest] = i;
                    rowsol[i] = jbest;
                    obj_free[jbest] = 0;
                    profit[i] = best;
                }
                /* compact unassigned */
                int w = 0;
                for (int t = 0; t < nfree; ++t) {
                    int i = unassigned[t];
                    if (rowsol[i] < 0) unassigned[w++] = i;
                }
                nfree = w;
            }
        }
        if (eps <= eps_target) break;
        eps *= 0.2;
        if (eps < eps_target) eps = eps_target;
        /* keep prices as warm start (standard epsilon scaling) */
    }

    npy_intp dims[1] = {n};
    PyObject* out = PyArray_SimpleNew(1, dims, NPY_INT32);
    int32_t* o = (int32_t*)PyArray_DATA((PyArrayObject*)out);
    int ok = 1;
    for (int i = 0; i < n; ++i) {
        if (rowsol[i] < 0) ok = 0;
        o[i] = (int32_t)rowsol[i];
    }
    if (!ok) {
        for (int i = 0; i < n; ++i) o[i] = -1;
    }
    free(price); free(profit); free(owner); free(rowsol); free(unassigned); free(obj_free);
    Py_DECREF(cost);
    return out;
}

