import numpy as np, time, auction_cert
from reference import Task
import ot

def certify(M, cols, price, tol=1e-7):
    """Assignment is optimal if M[i,j] + price[j] >= M[i,c_i] + price[c_i] - tol for all i,j.
    Equiv: min_j (M[i,j] + price[j]) >= M[i,c_i]+price[c_i] - tol.
    One row-min of (M + price)."""
