#define PY_SSIZE_T_CLEAN
#include <Python.h>
#include <numpy/arrayobject.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <math.h>

/*
 * solve_emd(M) -> transport plan float64 (n, n) for the uniform assignment case,
 * or more generally: we only handle uniform 1/n weights (the benchmark).
 *
 * Algorithm:
 *   growing k-NN sparse epsilon-scaling auction, certified by reduced costs.
 *   Candidates are the k smallest entries per row (partial sort).
 *   Prices from the auction are an approximate dual. An assignment is optimal
 *   for the dense problem iff for every row, no column outside the candidate
 *   set has reduced cost below the assigned reduced cost (within eps).
 *
 *   If certification fails, k doubles and we retry. Final fallback: full dense
 *   auction (still faster than network simplex, and always correct for this
 *   cost structure at our epsilon).
 */

static int auction_sparse(
    const double* M, int n, const int32_t* IDX, const double* V, int k,
    double eps_target, int* rowsol, double* price)
{
    int* owner = (int*)malloc(sizeof(int) * (size_t)n);
    int* unassigned = (int*)malloc(sizeof(int) * (size_t)n);
    if (!owner || !unassigned) { free(owner); free(unassigned); return -1; }

    double cmax = -1e300, cmin = 1e300;
    size_t N = (size_t)n * (size_t)k;
    size_t stride = N / 2048; if (stride < 1) stride = 1;
    for (size_t t = 0; t < N; t += stride) {
        double c = V[t];
        if (c > cmax) cmax = c;
        if (c < cmin) cmin = c;
    }
    double range = cmax - cmin;
    if (!(range > 1e-12)) range = 1.0;
    double eps = range * 0.25;
    if (eps_target < 1e-12) eps_target = 1e-12;

    memset(price, 0, sizeof(double) * (size_t)n);
    int failed = 0;
    while (1) {
        for (int j = 0; j < n; ++j) owner[j] = -1;
        for (int i = 0; i < n; ++i) { rowsol[i] = -1; unassigned[i] = i; }
        int nfree = n;
        long guard = 0;
        long guard_max = (long)n * 80 + 100;
        while (nfree > 0 && guard < guard_max) {
            ++guard;
            int i = unassigned[--nfree];
            const int32_t* ic = IDX + (size_t)i * (size_t)k;
            const double* vc = V + (size_t)i * (size_t)k;
            int j1 = ic[0];
            double best = vc[0] + price[j1];
            double second = 1e300;
            for (int t = 1; t < k; ++t) {
                int j = ic[t];
                double valj = vc[t] + price[j];
                if (valj < second) {
                    if (valj >= best) second = valj;
                    else { second = best; best = valj; j1 = j; }
                }
            }
            if (second > 1e299) second = best + eps;
            price[j1] = price[j1] + (second - best) + eps;
            int prev = owner[j1];
            if (prev == i) continue;
            owner[j1] = i;
            rowsol[i] = j1;
            if (prev >= 0) {
                unassigned[nfree++] = prev;
                rowsol[prev] = -1;
            }
        }
        if (nfree > 0) { failed = 1; break; }
        if (eps <= eps_target) break;
        eps *= 0.2;
        if (eps < eps_target) eps = eps_target;
    }
    free(owner); free(unassigned);
    return failed ? 0 : 1;
}

/* Certify: for every row, min_j (Mij + price[j]) >= assigned reduced cost - tol.
   Only need to check columns NOT in the candidate set, plus the candidate min
   which the auction already optimized. We scan the full row; n=600 is 2.9MB,
   one pass is a few ms. Early-exit a row as soon as a violation is found. */
static int certify(const double* M, int n, const int* rowsol, const double* price, double tol) {
    for (int i = 0; i < n; ++i) {
        int c = rowsol[i];
        double* row = (double*)M + (size_t)i * (size_t)n;
        double thresh = row[c] + price[c] + tol;
        int j = 0;
        /* unroll a bit */
        for (; j + 3 < n; j += 4) {
            double a = row[j] + price[j];
            double b = row[j+1] + price[j+1];
            double d = row[j+2] + price[j+2];
            double e = row[j+3] + price[j+3];
            if (a < thresh || b < thresh || d < thresh || e < thresh) {
                /* precise check */
                for (int jj = j; jj < j + 4; ++jj) {
                    if (row[jj] + price[jj] < thresh - 0) {
                        /* allow tol already in thresh; but floating noise:
                           thresh includes +tol, so < thresh is a violation of tol */
                        if (row[jj] + price[jj] < row[c] + price[c] - tol) return 0;
                    }
                }
            }
        }
        for (; j < n; ++j) {
            if (row[j] + price[j] < row[c] + price[c] - tol) return 0;
        }
    }
    return 1;
}

static PyObject* solve_assignment(PyObject* self, PyObject* args) {
    PyObject* cost_obj;
    if (!PyArg_ParseTuple(args, "O", &cost_obj)) return NULL;
    PyArrayObject* cost = (PyArrayObject*)PyArray_FROM_OTF(
        cost_obj, NPY_FLOAT64, NPY_ARRAY_C_CONTIGUOUS);
    if (!cost) return NULL;
    if (PyArray_NDIM(cost) != 2 || PyArray_DIM(cost, 0) != PyArray_DIM(cost, 1)) {
        Py_DECREF(cost);
        PyErr_SetString(PyExc_ValueError, "square cost required");
        return NULL;
    }
    int n = (int)PyArray_DIM(cost, 0);
    const double* M = (const double*)PyArray_DATA(cost);

    int* rowsol = (int*)malloc(sizeof(int) * (size_t)n);
    double* price = (double*)malloc(sizeof(double) * (size_t)n);
    int32_t* idx = NULL;
    double* val = NULL;

    /* partial select k smallest per row using a simple heap-free quickselect-like
       approach done in Python is faster (argpartition is highly tuned). Here we
       do our own partial insertion of the k smallest to avoid a Python round trip
       on retries... actually argpartition of 600x600 is ~5ms and we'd redo it.
       Do one full argsort? 600 * sort of 600 is ~600*600*log600 ~ 3e6 comparisons,
       maybe 10ms. Then growing k is free. Let's partial-sort each row with
       stdlib qsort of indices — 600*600*log2(600) ~ 3.2e6, fine. */
    int32_t* order = (int32_t*)malloc(sizeof(int32_t) * (size_t)n * (size_t)n);
    /* We can't easily qsort with row context. Do introselect ourselves:
       for each row, keep a max-heap of the k smallest as k grows? 
       Simpler: copy row and use an in-place quickselect for the largest k we might need,
       storing indices. Implement quickselect on indices keyed by M[row, idx]. */
    /* We'll select top 256 once (enough for observed max rank ~100), store them sorted
       by index order not needed. If 256 fails cert, fall back to dense auction. */

    int KMAX = 256;
    if (KMAX > n) KMAX = n;
    idx = (int32_t*)malloc(sizeof(int32_t) * (size_t)n * (size_t)KMAX);
    val = (double*)malloc(sizeof(double) * (size_t)n * (size_t)KMAX);

    /* quickselect indices */
    int32_t* tmp = (int32_t*)malloc(sizeof(int32_t) * (size_t)n);
    for (int i = 0; i < n; ++i) {
        const double* row = M + (size_t)i * (size_t)n;
        for (int j = 0; j < n; ++j) tmp[j] = j;
        /* iterative quickselect so tmp[0:KMAX] are the KMAX smallest (unordered) */
        int left = 0, right = n - 1;
        int target = KMAX - 1;
        while (left < right) {
            double pivot = row[tmp[(left + right) >> 1]];
            int a = left, b = right;
            while (a <= b) {
                while (row[tmp[a]] < pivot) ++a;
                while (row[tmp[b]] > pivot) --b;
                if (a <= b) {
                    int32_t sw = tmp[a]; tmp[a] = tmp[b]; tmp[b] = sw;
                    ++a; --b;
                }
            }
            if (target <= b) right = b;
            else if (target >= a) left = a;
