    if (eps_target < 1e-12) eps_target = 1e-12;

    int ok = 0;
    int ks[] = {48, 96, 160, 256};
    int nks = 4;
    for (int s = 0; s < nks; ++s) {
        int k = ks[s];
        if (k > KMAX) k = KMAX;
        /* compact first k candidates — they are an unordered subset of KMAX smallest,
           NOT the k smallest! Quickselect only partitioned at KMAX.
           So we must use all KMAX, or re-select. Use KMAX only, once. */
        break;
    }
    /* single shot at KMAX */
    ok = auction_sparse(M, n, idx, val, KMAX, eps_target, rowsol, price);
    if (ok) {
        ok = certify(M, n, rowsol, price, 1e-7 + 2.0 * eps_target * n);
    }
    if (!ok) {
        /* dense auction fallback */
        int32_t* didx = (int32_t*)malloc(sizeof(int32_t) * (size_t)n * (size_t)n);
        double* dval = (double*)malloc(sizeof(double) * (size_t)n * (size_t)n);
        for (int i = 0; i < n; ++i) {
