static double now() {
    struct timespec ts; clock_gettime(CLOCK_MONOTONIC, &ts);
    return ts.tv_sec + ts.tv_nsec*1e-9;
}

/* Floyd-Rivest / standard quickselect, median-of-3, on indices. */
static void ksmallest(const double* row, int n, int k, int32_t* idx) {
    for (int j = 0; j < n; ++j) idx[j] = j;
    int left = 0, right = n - 1, target = k - 1;
    while (left < right) {
        int mid = (left + right) >> 1;
        /* median of 3 */
        int ia = idx[left], ib = idx[mid], ic = idx[right];
        double va = row[ia], vb = row[ib], vc = row[ic];
        int p;
        if (va < vb) {
            if (vb < vc) p = ib;
            else if (va < vc) p = ic;
            else p = ia;
        } else {
            if (va < vc) p = ia;
            else if (vb < vc) p = ic;
            else p = ib;
        }
        double pivot = row[p];
        int a = left, b = right;
        while (a <= b) {
            while (row[idx[a]] < pivot) ++a;
            while (row[idx[b]] > pivot) --b;
            if (a <= b) {
                int32_t sw = idx[a]; idx[a] = idx[b]; idx[b] = sw;
                ++a; --b;
            }
        }
        if (target <= b) right = b;
        else if (target >= a) left = a;
        else break;
    }
}

