    double* M = malloc(sizeof(double)*(size_t)n*n);
    uint64_t s = 1;
    for (size_t i = 0; i < (size_t)n*n; ++i) {
        s = s * 6364136223846793005ULL + 1;
        M[i] = (s >> 11) * (1.0/9007199254740992.0);
    }
    int32_t* idx = malloc(sizeof(int32_t)*(size_t)n);
    int32_t* out = malloc(sizeof(int32_t)*(size_t)n*k);
    double t0 = now();
    for (int i = 0; i < n; ++i) {
        ksmallest(M + (size_t)i*n, n, k, idx);
        memcpy(out + (size_t)i*k, idx, sizeof(int32_t)*k);
    }
    double t1 = now();
    printf("ksmallest k=%d time=%.4f checksum=%d\n", k, t1-t0, out[123]);

    /* also time a heap of size k: for each row scan all n, maintain max-heap of k */
    t0 = now();
    for (int i = 0; i < n; ++i) {
        const double* row = M + (size_t)i*n;
        /* simple insertion of first k, then scan */
        int32_t heap_i[256];
        double heap_v[256];
        for (int t = 0; t < k; ++t) { heap_i[t] = t; heap_v[t] = row[t]; }
        /* build max heap */
        for (int t = k/2 - 1; t >= 0; --t) {
            int r = t;
            while (1) {
                int largest = r, l = 2*r+1, rr = l+1;
                if (l < k && heap_v[l] > heap_v[largest]) largest = l;
                if (rr < k && heap_v[rr] > heap_v[largest]) largest = rr;
                if (largest == r) break;
                double sv = heap_v[r]; heap_v[r] = heap_v[largest]; heap_v[largest] = sv;
                int32_t si = heap_i[r]; heap_i[r] = heap_i[largest]; heap_i[largest] = si;
                r = largest;
            }
        }
        for (int j = k; j < n; ++j) {
            if (row[j] < heap_v[0]) {
                heap_v[0] = row[j]; heap_i[0] = j;
                int r = 0;
                while (1) {
                    int largest = r, l = 2*r+1, rr = l+1;
                    if (l < k && heap_v[l] > heap_v[largest]) largest = l;
                    if (rr < k && heap_v[rr] > heap_v[largest]) largest = rr;
                    if (largest == r) break;
                    double sv = heap_v[r]; heap_v[r] = heap_v[largest]; heap_v[largest] = sv;
                    int32_t si = heap_i[r]; heap_i[r] = heap_i[largest]; heap_i[largest] = si;
                    r = largest;
                }
            }
        }
        memcpy(out + (size_t)i*k, heap_i, sizeof(int32_t)*k);
    }
    t1 = now();
    printf("heap k=%d time=%.4f checksum=%d\n", k, t1-t0, out[123]);
    return 0;
}
