    int32_t* scratch = (int32_t*)malloc(sizeof(int32_t) * (size_t)n);

    /* largest k we preselect */
    int KMAX = 192;
    if (KMAX > n - 1) KMAX = n - 1;
    if (KMAX < 1) KMAX = 1;
    int32_t* top = (int32_t*)malloc(sizeof(int32_t) * (size_t)n * (size_t)KMAX);
    double* topv = (double*)malloc(sizeof(double) * (size_t)n * (size_t)KMAX);

    for (int i = 0; i < n; ++i) {
        const double* row = M + (size_t)i * (size_t)n;
        ksmallest(row, n, KMAX, scratch);
        int32_t* di = top + (size_t)i * (size_t)KMAX;
        double* dv = topv + (size_t)i * (size_t)KMAX;
        for (int t = 0; t < KMAX; ++t) {
            di[t] = scratch[t];
            dv[t] = row[scratch[t]];
        }
    }

    double cmax = -1e300, cmin = 1e300;
    for (int i = 0; i < n; i += 2) {
        double c = M[(size_t)i * n];
        if (c > cmax) cmax = c;
        if (c < cmin) cmin = c;
    }
    double range = cmax - cmin;
    if (!(range > 1e-9)) range = 1.0;
    double eps_target = range / ((double)n * 1e6);
    if (eps_target < 1e-12) eps_target = 1e-12;
    double tol = eps_target * 4.0 + 1e-9;

    int ks[] = {40, 80, 128, 192};
    int success = 0;
    for (int s = 0; s < 4 && !success; ++s) {
        int k = ks[s];
        if (k > KMAX) k = KMAX;
        /* The first KMAX indices are the KMAX smallest but UNORDERED, so the
           first k of them are NOT the k smallest. Must re-select within top,
           or just always use a prefix after sorting each row's top-KMAX.
           Sort each row's KMAX by value once. */
        break;
    }
    /* sort each row's KMAX candidates by increasing cost (insertion, KMAX=192) */
    for (int i = 0; i < n; ++i) {
        int32_t* di = top + (size_t)i * (size_t)KMAX;
        double* dv = topv + (size_t)i * (size_t)KMAX;
        for (int t = 1; t < KMAX; ++t) {
            double v = dv[t]; int32_t id = di[t]; int p = t - 1;
            while (p >= 0 && dv[p] > v) { dv[p+1] = dv[p]; di[p+1] = di[p]; --p; }
            dv[p+1] = v; di[p+1] = id;
        }
    }
    for (int s = 0; s < 4 && !success; ++s) {
        int k = ks[s];
        if (k > KMAX) k = KMAX;
        /* pack prefix k into contiguous stride-k arrays */
        int32_t* IDX = (int32_t*)malloc(sizeof(int32_t) * (size_t)n * (size_t)k);
        double* V = (double*)malloc(sizeof(double) * (size_t)n * (size_t)k);
        for (int i = 0; i < n; ++i) {
            memcpy(IDX + (size_t)i * k, top + (size_t)i * KMAX, sizeof(int32_t) * k);
            memcpy(V + (size_t)i * k, topv + (size_t)i * KMAX, sizeof(double) * k);
        }
        int matched = auction(IDX, V, n, k, eps_target, rowsol, price);
        free(IDX); free(V);
        if (!matched) continue;
        if (certify(M, n, rowsol, price, tol)) success = 1;
    }

    if (!success) {
        /* dense fallback */
        int32_t* IDX = (int32_t*)malloc(sizeof(int32_t) * (size_t)n * (size_t)n);
        double* V = (double*)malloc(sizeof(double) * (size_t)n * (size_t)n);
        for (int i = 0; i < n; ++i) {
            const double* row = M + (size_t)i * n;
            int32_t* di = IDX + (size_t)i * n;
            double* dv = V + (size_t)i * n;
            for (int j = 0; j < n; ++j) { di[j] = j; dv[j] = row[j]; }
        }
        auction(IDX, V, n, n, eps_target, rowsol, price);
        free(IDX); free(V);
        success = 1;
    }

    npy_intp dims[1] = {n};
    PyObject* out = PyArray_SimpleNew(1, dims, NPY_INT32);
    int32_t* o = (int32_t*)PyArray_DATA((PyArrayObject*)out);
    for (int i = 0; i < n; ++i) o[i] = (int32_t)rowsol[i];
    free(rowsol); free(price); free(scratch); free(top); free(topv);
    Py_DECREF(cost);
    return out;
}

static PyMethodDef methods[] = {
    {"solve_assignment", solve_assignment, METH_VARARGS, ""},
    {NULL, NULL, 0, NULL}
};
static struct PyModuleDef moduledef = {
    PyModuleDef_HEAD_INIT, "emd_fast", NULL, -1, methods
};
PyMODINIT_FUNC PyInit_emd_fast(void) {
    import_array();
    return PyModule_Create(&moduledef);
}
