            const double* row = M + (size_t)i * (size_t)n;
            int j1 = 0;
            double best = row[0] + price[0];
            double second = 1e300;
            for (int j = 1; j < n; ++j) {
                double v = row[j] + price[j];
                if (v < second) {
                    if (v >= best) second = v;
                    else { second = best; best = v; j1 = j; }
                }
            }
            /* bid */
            double raise = (second - best) + eps;
            price[j1] += raise;
            int prev = owner[j1];
            if (prev == i) continue;
            /* if i already owned something else, release it */
            int old = rowsol[i];
            if (old >= 0 && old != j1 && owner[old] == i) {
                owner[old] = -1;
                /* object becomes free; someone may want it later via displacement only.
                   A free object is picked up because its price is low, so the next
                   bidder who scans will see it. No explicit enqueue needed. */
            }
            owner[j1] = i;
            rowsol[i] = j1;
            if (prev >= 0) {
                rowsol[prev] = -1;
                unassigned[nfree++] = prev;
            }
        }
        if (eps <= eps_target) break;
        /* scale epsilon down. Persons may no longer be happy. Re-queue anyone
           whose assignment is not (eps_new)-optimal, i.e. everyone, but keep prices
           and current matching as a warm start: unassign all and re-bid, prices stay.
           That's the same as resetting assignment. The WIN is keeping prices so the
           first scan already finds near-final bids and few displacements occur. */
        eps *= 0.2;
        if (eps < eps_target) eps = eps_target;
        /* requeue all, clear matching, KEEP prices */
        for (int j = 0; j < n; ++j) owner[j] = -1;
        nfree = n;
        for (int i = 0; i < n; ++i) { rowsol[i] = -1; unassigned[i] = i; }
    }

    npy_intp dims[1] = {n};
    PyObject* out = PyArray_SimpleNew(1, dims, NPY_INT32);
    int32_t* o = (int32_t*)PyArray_DATA((PyArrayObject*)out);
    int ok = 1;
    for (int i = 0; i < n; ++i) {
        if (rowsol[i] < 0) ok = 0;
        o[i] = (int32_t)rowsol[i];
    }
    if (!ok) { for (int i = 0; i < n; ++i) o[i] = -1; }
    free(price); free(owner); free(rowsol); free(unassigned);
    Py_DECREF(cost);
    return out;
}

static PyMethodDef methods[] = {
    {"solve_assignment", solve_assignment, METH_VARARGS, ""},
    {NULL, NULL, 0, NULL}
};
