/* Jonker-Volgenant LAPMOD-style dense solver.
 * Faithful to the algorithm used by scipy.optimize.linear_sum_assignment
 * (Jonker & Volgenant 1987), implemented from the published description
 * and the well-known lap.cpp public domain port by R. Jonker / A. Volgenant
 * as transcribed in many open implementations (e.g. the "lap.h" by
 * Volgenant, used by scipy via rectangular_lsap).
 *
 * This version follows the structure of:
 *   https://github.com/scipy/scipy/blob/main/scipy/optimize/rectangular_lsap/rectangular_lsap.cpp
 * which is the Crouse translation of the JV algorithm (BSD). We reimplement
 * the same control flow.
 */
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <math.h>
#include <string.h>
#include <time.h>
#include <float.h>

static double now(){struct timespec ts;clock_gettime(CLOCK_MONOTONIC,&ts);return ts.tv_sec+ts.tv_nsec*1e-9;}

/* Solve min-cost assignment. cost row-major n*n. col_for_row output. */
static int solve(const double* cost, int n, int* rowsol) {
    const double INF = DBL_MAX / 4;
    double* v = (double*)calloc(n, sizeof(double));
    double* u = (double*)calloc(n, sizeof(double));
    double* d = (double*)malloc(sizeof(double)*n);
    int* colsol = (int*)malloc(sizeof(int)*n);
    int* pred = (int*)malloc(sizeof(int)*n);
    int* free_rows = (int*)malloc(sizeof(int)*n);
    char* collabel = (char*)malloc(n); /* 0 unseen, 1 ready/todo, 2 scanned */
    int* todo = (int*)malloc(sizeof(int)*n);
    for (int i = 0; i < n; ++i) { rowsol[i] = -1; colsol[i] = -1; }

    /* COLUMN REDUCTION */
    for (int j = n-1; j >= 0; --j) {
        double minv = cost[j];
        int imin = 0;
        for (int i = 1; i < n; ++i) {
            double cij = cost[(size_t)i*n+j];
            if (cij < minv) { minv = cij; imin = i; }
        }
        v[j] = minv;
        if (rowsol[imin] < 0) { rowsol[imin] = j; colsol[j] = imin; }
    }
    int nfree = 0;
    for (int i = 0; i < n; ++i) if (rowsol[i] < 0) free_rows[nfree++] = i;

    /* REDUCTION TRANSFER */
    for (int i = 0; i < n; ++i) {
        int j1 = rowsol[i];
        if (j1 < 0) continue;
        const double* row = cost + (size_t)i*n;
        double minv = INF;
        for (int j = 0; j < n; ++j) {
            if (j == j1) continue;
            double red = row[j] - v[j];
            if (red < minv) minv = red;
        }
        v[j1] -= minv;
        u[i] = row[j1] - v[j1];
    }

    /* AUGMENTING ROW REDUCTION */
    for (int stage = 0; stage < 2; ++stage) {
        int k = 0, prev = nfree;
        nfree = 0;
        while (k < prev) {
            int i = free_rows[k++];
            const double* row = cost + (size_t)i*n;
            double umin = row[0] - v[0];
            int j1 = 0;
            double usub = INF;
            int j2 = -1;
            for (int j = 1; j < n; ++j) {
                double h = row[j] - v[j];
                if (h < usub) {
                    if (h >= umin) { usub = h; j2 = j; }
                    else { usub = umin; umin = h; j2 = j1; j1 = j; }
                }
            }
            i = i; /* silence */
            int i0 = colsol[j1];
            double u_i = umin;
            if (umin < usub) v[j1] -= (usub - umin);
            else if (i0 >= 0 && j2 >= 0) { j1 = j2; i0 = colsol[j1]; u_i = usub; }
            rowsol[free_rows[k-1]] = j1; /* wait, i may have been the free row */
            /* BUG risk: I reused i. Fix by using freerow variable. */
            /* rewritten below if this is wrong — we'll test. */
            int freerow = free_rows[k-1];
            rowsol[freerow] = j1;
            colsol[j1] = freerow;
            u[freerow] = cost[(size_t)freerow*n+j1] - v[j1];
            if (i0 >= 0 && i0 != freerow) {
                if (umin < usub) free_rows[--k] = i0;
                else free_rows[nfree++] = i0;
            }
        }
    }

    /* AUGMENTATION: shortest path with a todo list of columns at current min */
    for (int f = 0; f < nfree; ++f) {
        int freerow = free_rows[f];
        const double* frow = cost + (size_t)freerow*n;
        for (int j = 0; j < n; ++j) {
            d[j] = frow[j] - v[j];
            pred[j] = freerow;
            collabel[j] = 0;
        }
        int ntodo = 0;
        double minv = INF;
        int jmin = -1;
        for (int j = 0; j < n; ++j) {
            if (d[j] < minv) { minv = d[j]; jmin = j; ntodo = 0; todo[ntodo++] = j; }
            else if (d[j] == minv) todo[ntodo++] = j;
        }
        int endofpath = -1;
        while (1) {
            if (ntodo == 0) {
                /* find new min among unlabeled */
                minv = INF;
                for (int j = 0; j < n; ++j) if (!collabel[j] && d[j] < minv) minv = d[j];
                ntodo = 0;
                for (int j = 0; j < n; ++j) if (!collabel[j] && d[j] == minv) todo[ntodo++] = j;
                if (ntodo == 0) break;
            }
            int j = todo[--ntodo];
            if (collabel[j]) continue;
            collabel[j] = 1;
            int i_ass = colsol[j];
            if (i_ass < 0) { endofpath = j; break; }
            double h = cost[(size_t)i_ass*n + j] - v[j] - minv;
            const double* arow = cost + (size_t)i_ass*n;
            for (int jj = 0; jj < n; ++jj) {
                if (collabel[jj]) continue;
                double cred = arow[jj] - v[jj] - h;
                if (cred < d[jj]) {
                    d[jj] = cred;
                    pred[jj] = i_ass;
                    if (cred == minv) todo[ntodo++] = jj;
                    else if (cred < minv) {
                        /* numerical dip: treat as new minimum, reset todo */
                        minv = cred;
                        ntodo = 0;
                        todo[ntodo++] = jj;
                    }
                }
            }
        }
        double thresh = d[endofpath];
        for (int j = 0; j < n; ++j) if (collabel[j]) v[j] += d[j] - thresh;
        int j = endofpath;
        while (1) {
            int i = pred[j];
            colsol[j] = i;
            int jnext = rowsol[i];
            rowsol[i] = j;
            if (i == freerow) break;
            j = jnext;
        }
    }
    free(v); free(u); free(d); free(colsol); free(pred); free(free_rows); free(collabel); free(todo);
    return 0;
}

int main(){
    int n=600;
    double* M=malloc(sizeof(double)*(size_t)n*n);
    uint64_t rng=1;
    double* ax=malloc(8*n); /* dummy */
    double* pts=malloc(sizeof(double)*n*4);
    for(int i=0;i<n*4;i++){ rng=rng*6364136223846793005ULL+1; pts[i]=(rng>>11)*(1.0/9007199254740992.0); }
    for(int i=0;i<n;i++) for(int j=0;j<n;j++){
        double dx=pts[i]-pts[2*n+j], dy=pts[n+i]-pts[3*n+j];
        M[(size_t)i*n+j]=sqrt(dx*dx+dy*dy);
    }
    int* sol=malloc(sizeof(int)*n);
    double t0=now();
    solve(M,n,sol);
    printf("time %.4f sol0=%d\n", now()-t0, sol[0]);
    int* seen=calloc(n,sizeof(int)); int bad=0;
    for(int i=0;i<n;i++){ if(sol[i]<0||sol[i]>=n||seen[sol[i]]) bad++; else seen[sol[i]]=1; }
    printf("bad %d\n", bad);
    return 0;
}
