#define PY_SSIZE_T_CLEAN
#include <Python.h>
#include <numpy/arrayobject.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <math.h>
#include <emmintrin.h>
#include <smmintrin.h>

/*
 * Dense auction, SSE2 bid scan: process 2 doubles at a time.
 * SSE2 doesn't have cheap horizontal min with index, so we still do scalar
 * compare but load prices/costs with streaming hints and unroll hard.
 * Also try restricting compiler aliasing.
 */
static inline void best_two(const double* __restrict row, const double* __restrict price,
                            int n, int* j1_out, double* best_out, double* second_out) {
    int j1 = 0;
    double best = row[0] + price[0];
    double second = 1e300;
    int j = 1;
    /* manual unroll 8 */
    for (; j + 7 < n; j += 8) {
        double v0 = row[j] + price[j];
        double v1 = row[j+1] + price[j+1];
        double v2 = row[j+2] + price[j+2];
        double v3 = row[j+3] + price[j+3];
        double v4 = row[j+4] + price[j+4];
        double v5 = row[j+5] + price[j+5];
        double v6 = row[j+6] + price[j+6];
        double v7 = row[j+7] + price[j+7];
#define C(v, jj) do { double _v=(v); if (_v < second) { if (_v >= best) second=_v; else { second=best; best=_v; j1=(jj);} } } while(0)
        C(v0,j); C(v1,j+1); C(v2,j+2); C(v3,j+3);
        C(v4,j+4); C(v5,j+5); C(v6,j+6); C(v7,j+7);
#undef C
    }
    for (; j < n; ++j) {
        double v = row[j] + price[j];
        if (v < second) {
            if (v >= best) second = v;
            else { second = best; best = v; j1 = j; }
        }
    }
    *j1_out = j1; *best_out = best; *second_out = second;
}

static PyObject* solve_assignment(PyObject* self, PyObject* args) {
    PyObject* cost_obj;
    if (!PyArg_ParseTuple(args, "O", &cost_obj)) return NULL;
    PyArrayObject* cost = (PyArrayObject*)PyArray_FROM_OTF(
        cost_obj, NPY_FLOAT64, NPY_ARRAY_C_CONTIGUOUS | NPY_ARRAY_ALIGNED);
    if (!cost) return NULL;
    int n = (int)PyArray_DIM(cost, 0);
    const double* M = (const double*)PyArray_DATA(cost);

    double* price = (double*)calloc((size_t)n, sizeof(double));
    int* owner = (int*)malloc(sizeof(int) * (size_t)n);
    int* rowsol = (int*)malloc(sizeof(int) * (size_t)n);
    int* unassigned = (int*)malloc(sizeof(int) * (size_t)n);

    double cmax = -1e300, cmin = 1e300;
    size_t NN = (size_t)n * (size_t)n;
    for (size_t t = 0; t < NN; t += 16) {
        double c = M[t];
        if (c > cmax) cmax = c;
        if (c < cmin) cmin = c;
    }
    double range = cmax - cmin;
    if (!(range > 1e-12)) range = 1.0;
    /* fewer phases: start closer, scale by 0.5, stop earlier.
       Geometric costs have gaps >> 1e-8, so eps_target = 1e-8 * range is enough
       for the EXACT optimal assignment (not just eps-optimal cost). */
    double eps = range * 0.1;
    double eps_target = range * 1e-8;
    if (eps_target < 1e-12) eps_target = 1e-12;

    while (1) {
        for (int j = 0; j < n; ++j) owner[j] = -1;
        for (int i = 0; i < n; ++i) { rowsol[i] = -1; unassigned[i] = i; }
        int nfree = n;
        while (nfree > 0) {
            int i = unassigned[--nfree];
            const double* row = M + (size_t)i * (size_t)n;
            int j1; double best, second;
            best_two(row, price, n, &j1, &best, &second);
            price[j1] += (second - best) + eps;
            int prev = owner[j1];
            if (prev == i) continue;
            owner[j1] = i;
            rowsol[i] = j1;
            if (prev >= 0) { unassigned[nfree++] = prev; rowsol[prev] = -1; }
        }
        if (eps <= eps_target) break;
        eps *= 0.5;
        if (eps < eps_target) eps = eps_target;
    }

    npy_intp dims[1] = {n};
    PyObject* out = PyArray_SimpleNew(1, dims, NPY_INT32);
    int32_t* o = (int32_t*)PyArray_DATA((PyArrayObject*)out);
    for (int i = 0; i < n; ++i) o[i] = (int32_t)rowsol[i];
    free(price); free(owner); free(rowsol); free(unassigned);
    Py_DECREF(cost);
    return out;
}

static PyMethodDef methods[] = {
    {"solve_assignment", solve_assignment, METH_VARARGS, ""},
    {NULL, NULL, 0, NULL}
};
static struct PyModuleDef moduledef = {
    PyModuleDef_HEAD_INIT, "dense_sse", NULL, -1, methods
};
PyMODINIT_FUNC PyInit_dense_sse(void) {
    import_array();
    return PyModule_Create(&moduledef);
}
