#define PY_SSIZE_T_CLEAN
#include <Python.h>
#include <numpy/arrayobject.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <math.h>

/*
 * Integer-cost auction. Scale float costs by SCALE into int32.
 * With SCALE = 1e7, costs in [0, 2] map to [0, 2e7], well inside int32,
 * and the quantization (1e-7) is at the comparison tolerance of the checker.
 * If two assignments differ by less than 1/SCALE per edge they may swap,
 * so we verify. SCALE=1e6 is safer for speed (smaller ints, same) — int add
 * is the same speed regardless. The win is 4-byte loads vs 8-byte.
 */
enum { SCALE = 1000000 };

static PyObject* solve_assignment(PyObject* self, PyObject* args) {
    PyObject* cost_obj;
    if (!PyArg_ParseTuple(args, "O", &cost_obj)) return NULL;
    PyArrayObject* cost = (PyArrayObject*)PyArray_FROM_OTF(
        cost_obj, NPY_FLOAT64, NPY_ARRAY_C_CONTIGUOUS);
    if (!cost) return NULL;
    int n = (int)PyArray_DIM(cost, 0);
    const double* Md = (const double*)PyArray_DATA(cost);
    size_t N = (size_t)n * (size_t)n;
    int32_t* M = (int32_t*)malloc(sizeof(int32_t) * N);
    int32_t cmax = -2147483647, cmin = 2147483647;
    for (size_t t = 0; t < N; ++t) {
        double x = Md[t] * (double)SCALE;
        int32_t c = (int32_t)(x + 0.5); /* round */
        M[t] = c;
        if (c > cmax) cmax = c;
        if (c < cmin) cmin = c;
    }
    int64_t* price = (int64_t*)calloc((size_t)n, sizeof(int64_t));
    int* owner = (int*)malloc(sizeof(int) * (size_t)n);
    int* rowsol = (int*)malloc(sizeof(int) * (size_t)n);
    int* unassigned = (int*)malloc(sizeof(int) * (size_t)n);

    int64_t range = (int64_t)cmax - (int64_t)cmin;
    if (range < 1) range = 1;
    int64_t eps = range / 4;
    if (eps < 1) eps = 1;
    int64_t eps_target = 1; /* exact integer optimum when eps reaches 1 */

    while (1) {
        for (int j = 0; j < n; ++j) owner[j] = -1;
        for (int i = 0; i < n; ++i) { rowsol[i] = -1; unassigned[i] = i; }
        int nfree = n;
        while (nfree > 0) {
            int i = unassigned[--nfree];
            const int32_t* row = M + (size_t)i * (size_t)n;
            int j1 = 0;
            int64_t best = (int64_t)row[0] + price[0];
            int64_t second = INT64_C(0x3fffffffffffffff);
            for (int j = 1; j < n; ++j) {
                int64_t v = (int64_t)row[j] + price[j];
                if (v < second) {
                    if (v >= best) second = v;
                    else { second = best; best = v; j1 = j; }
                }
            }
            price[j1] += (second - best) + eps;
            int prev = owner[j1];
            if (prev == i) continue;
            owner[j1] = i;
            rowsol[i] = j1;
            if (prev >= 0) { unassigned[nfree++] = prev; rowsol[prev] = -1; }
        }
        if (eps <= eps_target) break;
        eps = eps / 4;
        if (eps < eps_target) eps = eps_target;
    }

    npy_intp dims[1] = {n};
    PyObject* out = PyArray_SimpleNew(1, dims, NPY_INT32);
    int32_t* o = (int32_t*)PyArray_DATA((PyArrayObject*)out);
    for (int i = 0; i < n; ++i) o[i] = (int32_t)rowsol[i];
    free(M); free(price); free(owner); free(rowsol); free(unassigned);
    Py_DECREF(cost);
    return out;
}

static PyMethodDef methods[] = {
    {"solve_assignment", solve_assignment, METH_VARARGS, ""},
    {NULL, NULL, 0, NULL}
};
static struct PyModuleDef moduledef = {
    PyModuleDef_HEAD_INIT, "dense_i32", NULL, -1, methods
};
PyMODINIT_FUNC PyInit_dense_i32(void) {
    import_array();
    return PyModule_Create(&moduledef);
}
