static double now(){struct timespec ts;clock_gettime(CLOCK_MONOTONIC,&ts);return ts.tv_sec+ts.tv_nsec*1e-9;}

static void scan_branch(const double* row, const double* price, int n, int* j1, double* best, double* second) {
    int jj = 0; double b = row[0]+price[0]; double s = 1e300;
    for (int j = 1; j < n; ++j) {
        double v = row[j]+price[j];
        if (v < s) { if (v >= b) s = v; else { s = b; b = v; jj = j; } }
    }
    *j1=jj; *best=b; *second=s;
}
static void scan_cmov(const double* row, const double* price, int n, int* j1, double* best, double* second) {
    int jj = 0; double b = row[0]+price[0]; double s = 1e300;
    for (int j = 1; j < n; ++j) {
        double v = row[j]+price[j];
        /* branchless update of best/second */
        double nb = v < b ? v : b;
        double ns = v < b ? b : (v < s ? v : s);
        int nj = v < b ? j : jj;
        b = nb; s = ns; jj = nj;
    }
    *j1=jj; *best=b; *second=s;
}

