/* Force cmov via volatile? or explicit branchless using bitwise on the comparison result.
   For doubles, the reliable way on x86 is:
     ucomisd + cmov
   We'll write a tiny asm helper. */
static void scan_asm(const double* row, const double* price, int n, int* j1, double* best, double* second) {
    int jj = 0;
    double b = row[0] + price[0];
    double s = 1e300;
    for (int j = 1; j < n; ++j) {
        double v = row[j] + price[j];
        /* use integer flags via asm cmov */
        int take_best = v < b;
        /* compiler barrier approach: multiply by boolean stored in double */
        double tb = (double)take_best;
        double ts = (double)(v < s);
        /* if take_best: second=best, best=v, j1=j
           else if v<s: second=v */
        double new_second = take_best ? b : (v < s ? v : s);
        double new_best = take_best ? v : b;
        int new_j = take_best ? j : jj;
        /* prevent the compiler from re-branching by volatile asm */
        asm volatile("" : "+x"(new_best), "+x"(new_second), "+r"(new_j) : : "memory");
        b = new_best; s = new_second; jj = new_j;
        (void)tb; (void)ts;
    }
    *j1 = jj; *best = b; *second = s;
}

static void scan_branch(const double* row, const double* price, int n, int* j1, double* best, double* second) {
    int jj=0; double b=row[0]+price[0]; double s=1e300;
    for(int j=1;j<n;j++){
        double v=row[j]+price[j];
        if(v<s){ if(v>=b) s=v; else {s=b; b=v; jj=j;} }
    }
    *j1=jj; *best=b; *second=s;
}

int main(){
    int n=600, reps=3000;
    double* row=malloc(sizeof(double)*n);
    double* price=calloc(n,sizeof(double));
    uint64_t rng=1;
    for(int j=0;j<n;j++){ rng=rng*6364136223846793005ULL+1; row[j]=(rng>>11)*(1.0/9007199254740992.0); }
    int j1; double b,s; double acc=0;
    double t0=now();
    for(int r=0;r<reps;r++){ scan_branch(row,price,n,&j1,&b,&s); acc+=b; }
    printf("branch %.4f\n", now()-t0);
    t0=now(); acc=0;
    for(int r=0;r<reps;r++){ scan_asm(row,price,n,&j1,&b,&s); acc+=b; }
    printf("asm    %.4f acc=%g j1=%d\n", now()-t0, acc, j1);
