static void solve(const double* M, int n, int* rowsol) {
    double* price = calloc(n, sizeof(double));
    int* owner = malloc(sizeof(int)*n);
    int* unassigned = malloc(sizeof(int)*n);
    int* prevsol = malloc(sizeof(int)*n);
    for (int i=0;i<n;i++) prevsol[i]=-2;
