    for (int phase=0; phase<30; ++phase) {
        for (int j=0;j<n;j++) owner[j]=-1;
        for (int i=0;i<n;i++){ rowsol[i]=-1; unassigned[i]=i; }
        int nfree=n;
        while (nfree>0) {
            int i = unassigned[--nfree];
            const double* row = M + (size_t)i*n;
            int j1=0;
            double best = row[0]+price[0];
            double second = 1e300;
            for (int j=1;j<n;j++) {
                double v = row[j]+price[j];
                double nb = v < best ? v : best;
                double ns = v < best ? best : (v < second ? v : second);
                int nj = v < best ? j : j1;
                best=nb; second=ns; j1=nj;
            }
            price[j1] += (second-best)+eps;
            int prev=owner[j1];
            if (prev==i) continue;
            owner[j1]=i; rowsol[i]=j1;
