/* Forward-reverse auction (Bertsekas), minimization form.
   Persons bid (forward). Then objects with slack are assigned in reverse
   by lowering price, which fills the matching much faster.
   Implementation sketch of the "auction algorithm with epsilon scaling"
   using BOTH forward and reverse iterations as in Bertsekas 1992.
*/
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <math.h>
#include <string.h>
#include <time.h>
static double now(){struct timespec ts;clock_gettime(CLOCK_MONOTONIC,&ts);return ts.tv_sec+ts.tv_nsec*1e-9;}

static void solve(const double* M, int n, int* rowsol) {
    double* price = calloc(n, sizeof(double));
    double* profit = malloc(sizeof(double)*n); /* person profit = -(best reduced cost) stored as best reduced cost */
    int* owner = malloc(sizeof(int)*n);
    int* unassigned = malloc(sizeof(int)*n);
    char* obj_assigned = malloc(n);
    for (int j=0;j<n;j++) owner[j]=-1;
    for (int i=0;i<n;i++) rowsol[i]=-1;

    double eps = 0.3;
    double target = 1e-8;
    long scans = 0;
    while (eps >= target) {
        /* reset matching, keep prices */
        for (int j=0;j<n;j++) { owner[j]=-1; obj_assigned[j]=0; }
        for (int i=0;i<n;i++) rowsol[i]=-1;
        int nfree = n;
        for (int i=0;i<n;i++) unassigned[i]=i;

        int iter = 0;
        while (nfree > 0 && iter++ < n*4) {
            /* FORWARD: each unassigned person bids for best object */
            int count = nfree;
            nfree = 0;
            for (int b=0;b<count;b++) {
                int i = unassigned[b];
                const double* row = M+(size_t)i*n;
                int j1=0; double best=row[0]+price[0]; double second=1e300;
                for (int j=1;j<n;j++) {
                    double v=row[j]+price[j];
                    double nb=v<best?v:best;
                    double ns=v<best?best:(v<second?v:second);
                    int nj=v<best?j:j1;
                    best=nb; second=ns; j1=nj;
                }
                scans++;
                profit[i]=best;
                price[j1] += (second-best)+eps;
                int prev = owner[j1];
                if (prev==i) continue;
                if (prev>=0) {
                    rowsol[prev]=-1;
                    unassigned[nfree++]=prev;
                }
                owner[j1]=i;
                rowsol[i]=j1;
            }
            if (nfree==0) break;
            /* REVERSE: look at unassigned persons and assign them to the
               best currently-free object without a full price war, by
               setting the object's price so the person is eps-happy relative
               to their second-best FREE object. This is a matching heuristic
               that still maintains eps-CS if we set the bid correctly.
               Skip if few free — forward handles it. */
        }
        eps *= 0.25;
    }
    printf("scans=%ld\n", scans);
    free(price); free(profit); free(owner); free(unassigned); free(obj_assigned);
}

int main(){
    int n=600;
    double* M=malloc(sizeof(double)*(size_t)n*n);
    uint64_t rng=1; double* pts=malloc(sizeof(double)*4*n);
    for(int i=0;i<4*n;i++){rng=rng*6364136223846793005ULL+1; pts[i]=(rng>>11)*(1.0/9007199254740992.0);}
    for(int i=0;i<n;i++) for(int j=0;j<n;j++){
        double dx=pts[i]-pts[2*n+j], dy=pts[n+i]-pts[3*n+j];
        M[(size_t)i*n+j]=sqrt(dx*dx+dy*dy);
    }
    int* sol=malloc(sizeof(int)*n);
    double t0=now();
    solve(M,n,sol);
    printf("time %.4f\n", now()-t0);
    return 0;
}
