                    double ns=v<best?best:(v<second?v:second);
                    int nj=v<best?j:j1;
                    best=nb; second=ns; j1=nj;
                }
                scans++;
                bid_j[i]=j1;
                bid_raise[i]=(second-best)+eps;
            }
            /* apply: for each object, highest raise wins (they all bid vs same price,
               the one with largest raise wanted it most) */
            for (int j=0;j<n;j++){ best_bidder[j]=-1; best_raise[j]=-1; }
            for (int b=0;b<nfree;b++) {
                int i=unassigned[b];
                int j=bid_j[i];
                if (bid_raise[i] > best_raise[j]) { best_raise[j]=bid_raise[i]; best_bidder[j]=i; }
            }
            int newfree=0;
            char* won = calloc(n,1);
            for (int j=0;j<n;j++) if (best_bidder[j]>=0) won[best_bidder[j]]=1;
            for (int b=0;b<nfree;b++) {
                int i=unassigned[b];
                if (!won[i]) {
                    /* lost this round, stays unassigned */
                    unassigned[newfree++]=i;
