/* Time a blocked best-two scan: process B rows together so price[] stays hot
   and row data is streamed. This is the Jacobi scan pattern. */
#define B 8
static void scan_block(const double* M, const double* price, int n, int i0, int* j1, double* best, double* second) {
    int jj[B]; double b[B], s[B];
    for (int t=0;t<B;t++) {
