            int nj = v < b[t] ? j : jj[t];
            b[t]=nb; s[t]=ns; jj[t]=nj;
        }
    }
    for (int t=0;t<B;t++) { j1[t]=jj[t]; best[t]=b[t]; second[t]=s[t]; }
